    owned = [
        {'worker_id': 'w1', 'ph': 301, 'th': 401, 'pid': 5001, 'assigned': True, 'resumed': True, 'exit_code': None, 'wait': None},
        {'worker_id': 'w2', 'ph': 302, 'th': 402, 'pid': 5002, 'assigned': True, 'resumed': True, 'exit_code': None, 'wait': None},
